/* GlobalStone — Corporate site styles (no build step) */

:root{
  /* Brand (OKLCH) */
  --navy-950: oklch(18% 0.03 252);
  --navy-900: oklch(22% 0.035 252);
  --navy-850: oklch(26% 0.03 252);
  --surface-0: oklch(99% 0.005 250);
  --surface-1: oklch(97% 0.008 250);
  --surface-2: oklch(94% 0.012 250);
  --text-0: oklch(20% 0.02 255);
  --text-1: oklch(38% 0.02 255);
  --text-2: oklch(55% 0.02 255);
  --line: oklch(86% 0.01 255);

  --accent: oklch(78% 0.13 200); /* refined teal */
  --accent-strong: oklch(66% 0.15 200);
  --gold: oklch(80% 0.14 75);

  --shadow-1: 0 10px 30px rgba(10, 22, 40, 0.14);
  --shadow-2: 0 22px 60px rgba(10, 22, 40, 0.18);

  --radius-sm: 10px;
  --radius-md: 16px;
  --radius-lg: 22px;

  --space-1: 4px;
  --space-2: 8px;
  --space-3: 16px;
  --space-4: 24px;
  --space-5: 32px;
  --space-6: 48px;
  --space-7: 64px;
  --space-8: 96px;

  --container: 1200px;

  --easing: cubic-bezier(.2,.8,.2,1);
}

*{ box-sizing:border-box; }
html{ scroll-behavior:smooth; }
body{
  margin:0;
  background: var(--surface-0);
  color: var(--text-0);
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial, "Apple Color Emoji", "Segoe UI Emoji";
  line-height:1.5;
  -webkit-font-smoothing: antialiased;
  text-rendering: geometricPrecision;
}
img{ max-width:100%; display:block; }
a{ color: inherit; text-decoration: none; }
a:hover{ text-decoration: none; }

.container{
  width:100%;
  max-width: var(--container);
  margin: 0 auto;
  padding: 0 var(--space-3);
}

@media (min-width: 640px){
  .container{ padding: 0 var(--space-4); }
}

/* Type */
.h-eyebrow{
  font-size: 12px;
  letter-spacing: .12em;
  text-transform: uppercase;
  color: var(--text-2);
}
.h1, h1{
  font-family: "Source Serif 4", ui-serif, Georgia, "Times New Roman", Times, serif;
  font-weight: 650;
  letter-spacing: -0.02em;
  line-height: 1.05;
}
.h2, h2{
  font-family: "Source Serif 4", ui-serif, Georgia, "Times New Roman", Times, serif;
  font-weight: 650;
  letter-spacing: -0.02em;
  line-height: 1.15;
}
.h3, h3{
  font-weight: 650;
  letter-spacing: -0.01em;
  line-height: 1.2;
}
.lede{ font-size: 18px; color: var(--text-1); }
.small{ font-size: 14px; color: var(--text-1); }
.muted{ color: var(--text-2); }

/* Buttons */
.btn{
  display:inline-flex;
  align-items:center;
  justify-content:center;
  gap: 10px;
  padding: 12px 16px;
  border-radius: 999px;
  border: 1px solid transparent;
  font-weight: 650;
  font-size: 14px;
  letter-spacing: 0.01em;
  cursor: pointer;
  transition: transform 160ms var(--easing), background 160ms var(--easing), border-color 160ms var(--easing), color 160ms var(--easing), box-shadow 160ms var(--easing);
  user-select:none;
}
.btn:active{ transform: translateY(1px); }
.btn-primary{ background: var(--accent-strong); color: oklch(99% 0 0); box-shadow: 0 12px 26px rgba(0, 125, 145, .24); }
.btn-primary:hover{ background: var(--accent); box-shadow: 0 18px 40px rgba(0, 125, 145, .24); }
.btn-secondary{ background: rgba(255,255,255,.08); color: #fff; border-color: rgba(255,255,255,.18); }
.btn-secondary:hover{ background: rgba(255,255,255,.14); }
.btn-ghost{ background: transparent; border-color: var(--line); color: var(--text-0); }
.btn-ghost:hover{ border-color: oklch(70% 0.02 255); }

:focus-visible{ outline: 2px solid var(--accent-strong); outline-offset: 3px; }

/* Top announcement */
.top-banner{
  background: linear-gradient(90deg, rgba(10,22,40,1) 0%, rgba(10,22,40,.96) 40%, rgba(10,22,40,.92) 100%);
  color: rgba(255,255,255,.92);
  border-bottom: 1px solid rgba(255,255,255,.08);
}
.top-banner .wrap{
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap: var(--space-3);
  padding: 10px 0;
}
.top-banner .wrap a{ color: rgba(255,255,255,.92); }
.top-banner .wrap .cta{
  display:inline-flex;
  align-items:center;
  gap: 10px;
  font-weight: 650;
  color: rgba(255,255,255,.95);
}

/* Header / Nav */
.site-header{
  position: sticky;
  top:0;
  z-index: 50;
  backdrop-filter: blur(10px);
  background: rgba(10,22,40,.82);
  border-bottom: 1px solid rgba(255,255,255,.08);
}
.site-header[data-theme="light"]{
  background: rgba(255,255,255,.86);
  border-bottom: 1px solid var(--line);
}

.navbar{
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap: var(--space-3);
  padding: 14px 0;
}
.brand{
  display:flex;
  align-items:center;
  gap: 12px;
  min-width: 180px;
}
.brand-mark{
  width: 40px;
  height: 40px;
  border-radius: 12px;
  background: radial-gradient(120% 120% at 20% 0%, rgba(255,255,255,.22) 0%, rgba(255,255,255,.06) 40%, rgba(255,255,255,0) 70%),
              linear-gradient(135deg, rgba(0,125,145,.9) 0%, rgba(10,22,40,1) 60%);
  box-shadow: 0 10px 26px rgba(0,0,0,.18);
}
.brand-name{
  display:flex;
  flex-direction:column;
  line-height:1.05;
}
.brand-name strong{ font-size: 14px; letter-spacing: .08em; text-transform: uppercase; }
.brand-name span{ font-size: 12px; opacity: .75; }

.site-header .brand-name strong, .site-header .nav a{ color: rgba(255,255,255,.92); }
.site-header[data-theme="light"] .brand-name strong,
.site-header[data-theme="light"] .nav a{ color: var(--text-0); }

.nav{
  display:none;
  align-items:center;
  gap: 6px;
}
.nav a{
  padding: 10px 12px;
  border-radius: 999px;
  font-weight: 650;
  font-size: 14px;
  color: rgba(255,255,255,.9);
  transition: background 160ms var(--easing), color 160ms var(--easing);
}
.nav a:hover{ background: rgba(255,255,255,.08); }
.site-header[data-theme="light"] .nav a:hover{ background: rgba(10,22,40,.06); }

.nav a[aria-current="page"]{ background: rgba(255,255,255,.12); }
.site-header[data-theme="light"] .nav a[aria-current="page"]{ background: rgba(10,22,40,.08); }

.nav-cta{ display:none; align-items:center; gap: 10px; }

.nav-btn{
  display:inline-flex;
  align-items:center;
  justify-content:center;
  height: 44px;
  width: 44px;
  border-radius: 12px;
  border: 1px solid rgba(255,255,255,.16);
  background: rgba(255,255,255,.08);
  color: rgba(255,255,255,.92);
}
.site-header[data-theme="light"] .nav-btn{
  border-color: var(--line);
  background: rgba(10,22,40,.04);
  color: var(--text-0);
}

@media (min-width: 1024px){
  .nav{ display:flex; }
  .nav-cta{ display:flex; }
  .nav-btn{ display:none; }
}

/* Mega menu */
.mega{
  position: absolute;
  left: 0;
  right: 0;
  top: 100%;
  transform-origin: top;
  opacity: 0;
  pointer-events: none;
  transform: translateY(-6px) scale(.99);
  transition: opacity 180ms var(--easing), transform 180ms var(--easing);
}
.mega[data-open="true"]{
  opacity: 1;
  pointer-events: auto;
  transform: translateY(0) scale(1);
}
.mega-panel{
  margin: 10px auto 0;
  max-width: var(--container);
  padding: 0 var(--space-3);
}
.mega-inner{
  border-radius: var(--radius-lg);
  background: rgba(255,255,255,.96);
  border: 1px solid rgba(10,22,40,.10);
  box-shadow: var(--shadow-2);
  overflow: hidden;
}

.mega-grid{
  display:grid;
  grid-template-columns: 1.25fr .75fr;
}
.mega-col{
  padding: var(--space-5);
}
.mega-col + .mega-col{
  border-left: 1px solid rgba(10,22,40,.10);
  background: linear-gradient(180deg, rgba(10,22,40,.02) 0%, rgba(10,22,40,.00) 55%);
}

.mega h4{ margin: 0 0 10px; font-size: 12px; letter-spacing: .12em; text-transform: uppercase; color: var(--text-2); }

.mega-links{
  display:grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}

.mega-item{
  border-radius: 14px;
  padding: 12px 12px;
  border: 1px solid rgba(10,22,40,.10);
  background: rgba(255,255,255,.75);
  transition: background 160ms var(--easing), border-color 160ms var(--easing), transform 160ms var(--easing);
}
.mega-item:hover{ transform: translateY(-1px); border-color: rgba(0,125,145,.35); background: rgba(0,125,145,.06); }
.mega-item strong{ display:block; font-size: 14px; }
.mega-item span{ display:block; font-size: 13px; color: var(--text-1); margin-top: 2px; }

.mega-side{
  display:grid;
  grid-template-columns: 1fr;
  gap: 12px;
}

.mega-side a{
  display:flex;
  align-items:flex-start;
  justify-content:space-between;
  gap: 14px;
  padding: 14px;
  border-radius: 14px;
  border: 1px solid rgba(10,22,40,.10);
  background: rgba(255,255,255,.8);
}
.mega-side a:hover{ border-color: rgba(10,22,40,.18); background: rgba(10,22,40,.03); }

.mega-side .tag{ font-size: 12px; letter-spacing: .08em; text-transform: uppercase; color: var(--text-2); }
.mega-side .title{ font-weight: 750; }
.mega-side .meta{ font-size: 13px; color: var(--text-1); }

/* Mobile nav */
.mobile{
  display:none;
  border-top: 1px solid rgba(255,255,255,.08);
  background: rgba(10,22,40,.96);
}
.site-header[data-theme="light"] .mobile{
  background: rgba(255,255,255,.98);
  border-top-color: var(--line);
}
.mobile[data-open="true"]{ display:block; }

.mobile .panel{
  padding: 12px 0 18px;
}

.accordion{
  border-radius: 16px;
  overflow: hidden;
  border: 1px solid rgba(255,255,255,.12);
  background: rgba(255,255,255,.06);
}
.site-header[data-theme="light"] .accordion{
  border-color: var(--line);
  background: rgba(10,22,40,.03);
}

.acc-btn{
  width: 100%;
  text-align:left;
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap: 12px;
  padding: 14px 14px;
  background: transparent;
  border:0;
  color: rgba(255,255,255,.92);
  font-weight: 750;
  font-size: 14px;
}
.site-header[data-theme="light"] .acc-btn{ color: var(--text-0); }

.acc-panel{
  max-height: 0;
  overflow:hidden;
  transition: max-height 220ms var(--easing);
}
.acc-panel[data-open="true"]{ max-height: 520px; }

.acc-links{ padding: 0 14px 14px; display:grid; gap: 8px; }
.acc-links a{
  padding: 12px 12px;
  border-radius: 12px;
  background: rgba(255,255,255,.08);
  border: 1px solid rgba(255,255,255,.12);
  color: rgba(255,255,255,.92);
}
.site-header[data-theme="light"] .acc-links a{
  background: rgba(10,22,40,.04);
  border-color: var(--line);
  color: var(--text-0);
}

/* Hero */
.hero{
  position: relative;
  overflow:hidden;
  background: radial-gradient(100% 80% at 20% 10%, rgba(0,125,145,.32) 0%, rgba(10,22,40,0) 55%),
              linear-gradient(180deg, rgba(10,22,40,1) 0%, rgba(10,22,40,.94) 38%, rgba(10,22,40,.84) 100%);
  color: rgba(255,255,255,.92);
}
.hero .hero-bg{
  position:absolute;
  inset:0;
  background-size: cover;
  background-position: center;
  filter: saturate(0.9) contrast(1.05);
  opacity: .36;
}
.hero .hero-overlay{
  position:absolute;
  inset:0;
  background: linear-gradient(90deg, rgba(10,22,40,.92) 0%, rgba(10,22,40,.82) 40%, rgba(10,22,40,.64) 100%);
}
.hero .content{
  position:relative;
  padding: var(--space-7) 0 var(--space-6);
}

.hero .grid{
  display:grid;
  grid-template-columns: 1fr;
  gap: var(--space-5);
  align-items:end;
}
@media (min-width: 1024px){
  .hero .grid{ grid-template-columns: 1.15fr .85fr; }
}

.hero h1{ font-size: clamp(34px, 4vw, 56px); margin: 10px 0 12px; }
.hero .lede{ color: rgba(255,255,255,.78); max-width: 60ch; }

.hero-card{
  border-radius: var(--radius-lg);
  background: rgba(255,255,255,.06);
  border: 1px solid rgba(255,255,255,.12);
  padding: var(--space-4);
  box-shadow: 0 18px 70px rgba(0,0,0,.18);
}

.kpi{
  display:grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
  margin-top: var(--space-3);
}
.kpi .item{
  border-radius: 14px;
  padding: 12px;
  background: rgba(255,255,255,.06);
  border: 1px solid rgba(255,255,255,.12);
}
.kpi .item strong{ font-size: 22px; }
.kpi .item span{ display:block; font-size: 12px; opacity: .75; margin-top: 2px; }

/* Sections */
.section{ padding: var(--space-7) 0; }
.section.tight{ padding: var(--space-6) 0; }
.section .head{
  display:flex;
  align-items:flex-end;
  justify-content:space-between;
  gap: var(--space-4);
  margin-bottom: var(--space-4);
}
.section .head h2{ margin:0; font-size: clamp(26px, 2.5vw, 38px); }
.section .head .lede{ margin:0; max-width: 70ch; }

.surface{
  border-radius: var(--radius-lg);
  background: var(--surface-1);
  border: 1px solid var(--line);
  box-shadow: var(--shadow-1);
}

/* Cards / grids */
.grid-3{ display:grid; grid-template-columns: 1fr; gap: var(--space-3); }
.grid-2{ display:grid; grid-template-columns: 1fr; gap: var(--space-3); }
@media (min-width: 860px){
  .grid-3{ grid-template-columns: repeat(3, minmax(0, 1fr)); }
  .grid-2{ grid-template-columns: repeat(2, minmax(0, 1fr)); }
}

.card{
  border-radius: var(--radius-md);
  border: 1px solid var(--line);
  background: rgba(255,255,255,.92);
  overflow:hidden;
  transition: transform 160ms var(--easing), box-shadow 160ms var(--easing), border-color 160ms var(--easing);
}
.card:hover{ transform: translateY(-2px); border-color: rgba(0,125,145,.30); box-shadow: 0 18px 50px rgba(10,22,40,.12); }
.card .thumb{ height: 160px; background-size: cover; background-position: center; filter: saturate(.95) contrast(1.05); }
.card .body{ padding: var(--space-4); }
.card .meta{ display:flex; gap: 10px; align-items:center; color: var(--text-2); font-size: 12px; letter-spacing: .08em; text-transform: uppercase; }
.card h3{ margin: 10px 0 8px; font-size: 18px; }
.card p{ margin: 0; color: var(--text-1); }
.card .link{ margin-top: 14px; display:inline-flex; gap: 8px; align-items:center; font-weight: 750; color: var(--accent-strong); }

.badge{
  display:inline-flex;
  align-items:center;
  gap: 8px;
  padding: 6px 10px;
  border-radius: 999px;
  border: 1px solid rgba(255,255,255,.16);
  background: rgba(255,255,255,.08);
  color: rgba(255,255,255,.86);
  font-size: 12px;
  letter-spacing: .08em;
  text-transform: uppercase;
}

/* Announcement band (home) */
.announce{
  border-radius: var(--radius-lg);
  background: linear-gradient(90deg, rgba(0,125,145,.16) 0%, rgba(255,255,255,.0) 45%),
              linear-gradient(180deg, rgba(10,22,40,1) 0%, rgba(10,22,40,.92) 100%);
  color: rgba(255,255,255,.92);
  border: 1px solid rgba(255,255,255,.10);
  box-shadow: 0 24px 80px rgba(0,0,0,.18);
  padding: var(--space-5);
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap: var(--space-4);
}

/* What we do tabs */
.tabs{
  display:grid;
  grid-template-columns: 1fr;
  gap: var(--space-4);
}
@media (min-width: 1024px){
  .tabs{ grid-template-columns: 0.42fr 0.58fr; }
}

.tablist{
  border-radius: var(--radius-lg);
  border: 1px solid var(--line);
  background: rgba(255,255,255,.92);
  overflow:hidden;
}
.tabbtn{
  width: 100%;
  padding: 16px 18px;
  display:flex;
  align-items:flex-start;
  justify-content:space-between;
  gap: 14px;
  border:0;
  background: transparent;
  text-align:left;
  cursor:pointer;
  transition: background 160ms var(--easing);
}
.tabbtn:hover{ background: rgba(10,22,40,.04); }
.tabbtn[aria-selected="true"]{ background: rgba(0,125,145,.08); }
.tabbtn strong{ font-size: 14px; }
.tabbtn span{ display:block; font-size: 13px; color: var(--text-1); margin-top: 2px; }

.tabpanel{
  border-radius: var(--radius-lg);
  border: 1px solid var(--line);
  background: linear-gradient(180deg, rgba(255,255,255,.96) 0%, rgba(255,255,255,.90) 100%);
  box-shadow: var(--shadow-1);
  overflow:hidden;
}
.tabpanel .inner{ padding: var(--space-5); }
.tabpanel .inner h3{ margin: 0 0 10px; font-size: 22px; }
.tabpanel .inner p{ margin: 0 0 18px; color: var(--text-1); }

/* Capability grid */
.cap-grid{ display:grid; grid-template-columns: 1fr; gap: var(--space-3); }
@media (min-width: 860px){ .cap-grid{ grid-template-columns: repeat(3, minmax(0, 1fr)); } }
.cap-card{
  border-radius: var(--radius-md);
  border: 1px solid var(--line);
  background: rgba(255,255,255,.92);
