  grid-template-columns: 1fr;
  gap: var(--space-5);
}
@media (min-width: 1024px){
  .two-col{ grid-template-columns: 1.2fr 0.8fr; }
}

.sidebar{
  border-radius: var(--radius-lg);
  border: 1px solid var(--line);
  background: rgba(255,255,255,.92);
  padding: var(--space-4);
}
.sidebar h4{ margin: 0 0 12px; font-size: 12px; letter-spacing:.12em; text-transform: uppercase; color: var(--text-2); }
.sidebar a{
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap: 12px;
  padding: 12px 12px;
  border-radius: 14px;
  border: 1px solid rgba(10,22,40,.08);
  background: rgba(10,22,40,.03);
}
.sidebar a:hover{ background: rgba(0,125,145,.06); border-color: rgba(0,125,145,.25); }

/* Carousel */
.carousel{
  border-radius: var(--radius-lg);
  border: 1px solid var(--line);
  background: rgba(255,255,255,.92);
  overflow:hidden;
}
.carousel .viewport{ overflow:hidden; }
.carousel .track{ display:flex; transition: transform 420ms var(--easing); }
.carousel .slide{ min-width: 100%; padding: var(--space-5); }
.carousel .controls{
