}

.footer a{ color: rgba(255,255,255,.86); }
.footer a:hover{ color: rgba(255,255,255,.98); }
.footer .links{ display:grid; grid-template-columns: repeat(2, minmax(0,1fr)); gap: 10px; }
.footer .fine{ padding: 14px 0; border-top: 1px solid rgba(255,255,255,.08); font-size: 13px; color: rgba(255,255,255,.68); }

/* Helpers */
.sep{ height:1px; background: var(--line); }
.icon{ width: 18px; height: 18px; display:inline-block; }

@media (prefers-reduced-motion: reduce){
  *{ transition: none !important; scroll-behavior: auto !important; }
}
