.sidebar a{
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap: 12px;
  padding: 12px 12px;
  border-radius: 14px;
  border: 1px solid rgba(10,22,40,.08);
  background: rgba(10,22,40,.03);
}
.sidebar a:hover{ background: rgba(0,125,145,.06); border-color: rgba(0,125,145,.25); }

/* Carousel */
.carousel{
  border-radius: var(--radius-lg);
  border: 1px solid var(--line);
  background: rgba(255,255,255,.92);
  overflow:hidden;
}
.carousel .viewport{ overflow:hidden; }
.carousel .track{ display:flex; transition: transform 420ms var(--easing); }
.carousel .slide{ min-width: 100%; padding: var(--space-5); }
.carousel .controls{
  display:flex;
  align-items:center;
  justify-content:space-between;
  padding: 12px 12px;
  border-top: 1px solid rgba(10,22,40,.08);
  background: rgba(10,22,40,.02);
}
.carousel .dots{ display:flex; gap: 8px; }
.carousel .dot{
  width: 8px; height: 8px; border-radius: 999px;
  border: 0; cursor:pointer;
  background: rgba(10,22,40,.20);
}
.carousel .dot[aria-current="true"]{ background: var(--accent-strong); }

/* Footer */
.footer{
  background: linear-gradient(180deg, rgba(10,22,40,1) 0%, rgba(10,22,40,.98) 100%);
  color: rgba(255,255,255,.86);
  border-top: 1px solid rgba(255,255,255,.08);
}
.footer .grid{
  display:grid;
  grid-template-columns: 1fr;
  gap: var(--space-4);
  padding: var(--space-7) 0;
}
@media (min-width: 860px){
  .footer .grid{ grid-template-columns: 1.2fr .8fr; }
}

.footer a{ color: rgba(255,255,255,.86); }
.footer a:hover{ color: rgba(255,255,255,.98); }
.footer .links{ display:grid; grid-template-columns: repeat(2, minmax(0,1fr)); gap: 10px; }
.footer .fine{ padding: 14px 0; border-top: 1px solid rgba(255,255,255,.08); font-size: 13px; color: rgba(255,255,255,.68); }

/* Helpers */
.sep{ height:1px; background: var(--line); }
.icon{ width: 18px; height: 18px; display:inline-block; }

@media (prefers-reduced-motion: reduce){
  *{ transition: none !important; scroll-behavior: auto !important; }
}
