cd /app && python - <<'PY'
import re, glob
files=glob.glob('output/*.html')
ref=set()
for f in files:
    txt=open(f,'r',encoding='utf-8').read()
    for m in re.findall(r'href="([^"]+)"', txt):
        if m.startswith(('http','mailto:','#')): continue
        if m.startswith('assets/'): continue
        if '#' in m:
            m=m.split('#',1)[0]
        if m:
            ref.add(m)

missing=[]
for r in sorted(ref):
    if not (r in [f.split('/')[-1] for f in files]):
        # allow same-folder file exists
        if not glob.glob('output/'+r):
            missing.append(r)
print('internal refs:', len(ref))
print('missing:', missing)
